        if (cp == '\f') return "'\\f'"; if (cp == '\r') return "'\\r'"; if (cp == '"') return "'\\\"'";
        if (cp == '\\') return "'\\\\'";
        if (0x20 <= cp && cp < 0x7F) return "'" + (char) cp + "'";
        return "'" + String.format("%04X", cp) + "'";
    }
