        for (int cp = 0; cp <= 0x10FFFF; cp++) {
            n++;
            String h = CharSweep.helperForm(cp);
            if (CharSweep.walkForm(cp).equals(h)) { walkHelper++; if (cp > 0x7E || cp < 0x20) agree.append(String.format("%04X ", cp)); }
            if (!CharSweep.completedForm(cp).equals(h)) completedHelper++;
            if (!CharSweep.hexForm(cp).equals(h)) hexHelper++;
            if (!CharSweep.hexForm(cp).toLowerCase().equals(h.toLowerCase())) hexLowerHelper++;
        }
        System.out.println("code points " + n + "; walk's form equals the helper's at " + walkHelper + " (outside printable ASCII: " + agree + ")");
        System.out.println("option (d) differs from the helper at " + completedHelper + "; option (c) uppercase at " + hexHelper + ", lowercase at " + hexLowerHelper);
    }
}
